-- Generated. Exact installed state and history; no account/question content.
BEGIN READ ONLY;
SET LOCAL search_path=public,pg_catalog;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
WITH checks(name,ok) AS (
 SELECT 'administrator_history_matches',coalesce((EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261103020000' AND name='admin_user_deletion' AND cardinality(statements)=1 AND md5(statements[1])='d11ccb83ad64a84db35645599c39f9eb')),false)
 UNION ALL
 SELECT 'arena_history_matches',coalesce((EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000100' AND name='arena_game' AND cardinality(statements)=1 AND md5(statements[1])='5ec05f163e84b91b4ee115e2716978db')),false)
 UNION ALL
 SELECT 'course_history_matches',coalesce((EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105010000' AND name='course_login_access' AND cardinality(statements)=1 AND md5(statements[1])='cc8aba077c306f281bce8aeab9da7c1a')),false)
 UNION ALL
 SELECT 'course_functions_installed',coalesce((EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.course_topic_visible(uuid,uuid)') AND md5(regexp_replace(replace(prosrc,E'\r',''),E'[ \t]+\n',E'\n','g'))='8b88df94abb2b1f5120bae7860235bb9' AND prosecdef AND provolatile='s' AND proconfig=ARRAY['search_path=public, extensions'] AND pg_get_userbyid(proowner)='postgres') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.course_lesson_visible(uuid)') AND md5(regexp_replace(replace(prosrc,E'\r',''),E'[ \t]+\n',E'\n','g'))='680d5328bb2afc88d46eca84d8d9927f' AND prosecdef AND provolatile='s' AND proconfig=ARRAY['search_path=public, extensions'] AND pg_get_userbyid(proowner)='postgres') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.get_course_outline_entry(uuid,uuid)') AND md5(regexp_replace(replace(prosrc,E'\r',''),E'[ \t]+\n',E'\n','g'))='3f66e61bbb3f30df1b06d4cbc791b0b7' AND prosecdef AND provolatile='s' AND proconfig=ARRAY['search_path=public, extensions'] AND pg_get_userbyid(proowner)='postgres')),false)
 UNION ALL
 SELECT 'course_security_dependencies_match',coalesce((EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='course_lesson_courses' AND policyname='lesson_binding_read' AND cmd='SELECT' AND permissive='PERMISSIVE' AND roles=ARRAY['public']::name[] AND qual='(has_admin_module(''courses''::text) OR course_topic_visible(course_id, topic_id))' AND with_check IS NULL) AND EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.course_lesson_courses') AND relrowsecurity) AND EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='course_lesson_videos' AND policyname='lesson_video_read' AND cmd='SELECT' AND permissive='PERMISSIVE' AND roles=ARRAY['public']::name[] AND qual='(has_admin_module(''courses''::text) OR course_lesson_visible(lesson_id))' AND with_check IS NULL) AND EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.course_lesson_videos') AND relrowsecurity) AND EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='course_lessons' AND policyname='lesson_read' AND cmd='SELECT' AND permissive='PERMISSIVE' AND roles=ARRAY['public']::name[] AND qual='(has_admin_module(''courses''::text) OR course_lesson_visible(id))' AND with_check IS NULL) AND EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.course_lessons') AND relrowsecurity) AND EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='course_videos' AND policyname='course_published_video_read' AND cmd='SELECT' AND permissive='PERMISSIVE' AND roles=ARRAY['public']::name[] AND qual='(has_admin_module(''courses''::text) OR (EXISTS ( SELECT 1
   FROM course_lesson_videos v
  WHERE ((v.video_id = course_videos.id) AND course_lesson_visible(v.lesson_id)))))' AND with_check IS NULL) AND EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.course_videos') AND relrowsecurity) AND EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='course_game_read' AND cmd='SELECT' AND permissive='PERMISSIVE' AND roles=ARRAY['public']::name[] AND qual='((bucket_id = ''course-games''::text) AND (has_admin_storage_access(bucket_id) OR (EXISTS ( SELECT 1
   FROM course_lessons l
  WHERE ((l.game_path = objects.name) AND course_lesson_visible(l.id))))))' AND with_check IS NULL) AND EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('storage.objects') AND relrowsecurity) AND coalesce(has_function_privilege('anon',to_regprocedure('public.course_topic_visible(uuid,uuid)'),'EXECUTE'),false) AND coalesce(has_function_privilege('authenticated',to_regprocedure('public.course_topic_visible(uuid,uuid)'),'EXECUTE'),false) AND coalesce(has_function_privilege('anon',to_regprocedure('public.course_lesson_visible(uuid)'),'EXECUTE'),false) AND coalesce(has_function_privilege('authenticated',to_regprocedure('public.course_lesson_visible(uuid)'),'EXECUTE'),false) AND coalesce(has_function_privilege('anon',to_regprocedure('public.get_course_outline_entry(uuid,uuid)'),'EXECUTE'),false) AND coalesce(has_function_privilege('authenticated',to_regprocedure('public.get_course_outline_entry(uuid,uuid)'),'EXECUTE'),false)),false)
 UNION ALL
 SELECT 'arena_catalog_matches',coalesce(((-- Only system catalogs; never reads questions, answers or account rows.
-- Ignore CRLF and trailing horizontal whitespace only, not SQL tokens or comments.
SELECT jsonb_build_object(
 'tables',coalesce((SELECT jsonb_agg(jsonb_build_object(
  'name',c.relname,'kind',c.relkind,'persistence',c.relpersistence,'owner',pg_get_userbyid(c.relowner),
  'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
  'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY x.grantee::regrole::text,x.privilege_type) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
  'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid),k.convalidated,k.condeferrable,k.condeferred) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
  'indexes',(SELECT jsonb_agg(jsonb_build_array(pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready) ORDER BY pg_get_indexdef(i.indexrelid)) FROM pg_index i WHERE i.indrelid=c.oid),
  'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=c.relname),
  'triggers',(SELECT jsonb_agg(jsonb_build_array(pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)
 ) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('arena_questions','arena_question_issues')),'[]'::jsonb),
 'functions',coalesce((SELECT jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),
  'definition_md5',md5(regexp_replace(replace(pg_get_functiondef(p.oid),E'\r',''),E'[ \t]+\n',E'\n','g')),
  'acl',(SELECT jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY x.grantee::regrole::text,x.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x),
  'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')
 ) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('arena_catalog','arena_next_question','arena_submit_answer')),'[]'::jsonb),
 'client_table_access',coalesce((SELECT jsonb_agg(jsonb_build_array(c.relname,r.name,has_table_privilege(r.name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),has_any_column_privilege(r.name,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')) ORDER BY c.relname,r.name) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN (VALUES('anon'),('authenticated')) r(name) WHERE n.nspname='public' AND c.relname IN ('arena_questions','arena_question_issues')),'[]'::jsonb)
) AS arena_catalog) = '{"tables":[{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false],["service_role","DELETE",false],["service_role","INSERT",false],["service_role","MAINTAIN",false],["service_role","REFERENCES",false],["service_role","SELECT",false],["service_role","TRIGGER",false],["service_role","TRUNCATE",false],["service_role","UPDATE",false]],"rls":true,"kind":"r","name":"arena_question_issues","owner":"postgres","columns":[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"user_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"run_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"question_id","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"option_order","type":"smallint[]","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"issued_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"selected_index","type":"smallint","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"is_correct","type":"boolean","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"answered_at","type":"timestamp with time zone","default":null,"identity":"","not_null":false,"generated":""}],"indexes":[["CREATE INDEX arena_question_issues_user_question_idx ON public.arena_question_issues USING btree (user_id, question_id, issued_at DESC)",true,true],["CREATE INDEX arena_question_issues_user_time_idx ON public.arena_question_issues USING btree (user_id, issued_at DESC)",true,true],["CREATE UNIQUE INDEX arena_question_issues_pkey ON public.arena_question_issues USING btree (id)",true,true]],"policies":null,"triggers":null,"force_rls":false,"constraints":[["arena_question_issues_option_order_check","CHECK ((cardinality(option_order) = 4))",true,false,false],["arena_question_issues_pkey","PRIMARY KEY (id)",true,false,false],["arena_question_issues_question_id_fkey","FOREIGN KEY (question_id) REFERENCES arena_questions(id) ON DELETE CASCADE",true,false,false],["arena_question_issues_selected_index_check","CHECK (((selected_index >= 0) AND (selected_index <= 3)))",true,false,false],["arena_question_issues_user_id_fkey","FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE",true,false,false]],"persistence":"p"},{"acl":[["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false],["service_role","DELETE",false],["service_role","INSERT",false],["service_role","MAINTAIN",false],["service_role","REFERENCES",false],["service_role","SELECT",false],["service_role","TRIGGER",false],["service_role","TRUNCATE",false],["service_role","UPDATE",false]],"rls":true,"kind":"r","name":"arena_questions","owner":"postgres","columns":[{"acl":null,"name":"id","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"unit","type":"smallint","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"tier","type":"smallint","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"topic","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"stem","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"options","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"explanation","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"graph","type":"jsonb","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"table_html","type":"text","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"active","type":"boolean","default":"true","identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","identity":"","not_null":true,"generated":""}],"indexes":[["CREATE INDEX arena_questions_unit_tier_idx ON public.arena_questions USING btree (unit, tier) WHERE active",true,true],["CREATE UNIQUE INDEX arena_questions_pkey ON public.arena_questions USING btree (id)",true,true]],"policies":null,"triggers":null,"force_rls":false,"constraints":[["arena_questions_options_check","CHECK (((jsonb_typeof(options) = ''array''::text) AND (jsonb_array_length(options) = 4)))",true,false,false],["arena_questions_pkey","PRIMARY KEY (id)",true,false,false],["arena_questions_tier_check","CHECK (((tier >= 1) AND (tier <= 3)))",true,false,false],["arena_questions_unit_check","CHECK (((unit >= 1) AND (unit <= 10)))",true,false,false]],"persistence":"p"}],"functions":[{"acl":[["authenticated","EXECUTE",false],["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"arena_catalog()","anon_execute":false,"definition_md5":"4096bf02378fbd9b48c95646e2330a90","authenticated_execute":true},{"acl":[["authenticated","EXECUTE",false],["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"arena_next_question(uuid,integer[],integer,integer,boolean)","anon_execute":false,"definition_md5":"6a498e67a01b861596d8e75960797a47","authenticated_execute":true},{"acl":[["authenticated","EXECUTE",false],["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"arena_submit_answer(uuid,integer)","anon_execute":false,"definition_md5":"5fa73f7129d129b26925bcdd4aa58088","authenticated_execute":true}],"client_table_access":[["arena_question_issues","anon",false,false],["arena_question_issues","authenticated",false,false],["arena_questions","anon",false,false],["arena_questions","authenticated",false,false]]}'::jsonb),false)
) SELECT jsonb_build_object('all_checks_pass',bool_and(ok),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS reconciliation FROM checks;
COMMIT;
